@startuml

class Course {
  + name : string
}

class Edition {
}

class Lesson {
  + date : date
  + startTime : time
  + duration : string
}

abstract class Teacher {
  + name : string
}

class InternalTeacher extends Teacher {}

class ExternalTeacher extends Teacher {}

abstract class Participant {}

class Student extends Participant {}

class Auditor extends Participant {}

class Room {
  + name : string
}

class Resource {
  + name : string
}

Course "1" -- "*" Edition
Course "1" -- "1" InternalTeacher : responsible
Course "0..*" -- "0..*" Teacher : preallocated
Edition "1" *-- "1..*" Lesson
Lesson "1..*" -- "1..*" Teacher : gives
Lesson "0..*" -- "0..*" Resource
Lesson "0..*" -- "1" Room
Edition "1" -- "1..*" Participant : enrolled

@enduml

